python
def neighborNotesPositiveProofStrip(readings, k):
    a=readings
    out=[]
    for i in range(1,len(a)): out.append(a[i]-a[i-1])
    return [x for x in out if x>0]


java
class Solution {
  public int[] neighborNotesPositiveProofStrip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int i=1;i<a.length;i++)out.add(a[i]-a[i-1]);}
    return out.stream().filter(x->x>0).mapToInt(Integer::intValue).toArray();
  }
}
